  font-family: var(--mono); font-variant-numeric: tabular-nums;
  color: var(--ink);
}
</style>
<div class="lab">
  <div class="controls">
    <label for="step">步数</label>
    <input type="range" id="step" min="0" max="50" step="1" value="5">
    <span class="val" id="stepVal">5</span>
  </div>
  <div class="stage-wrap" id="stageWrap">
    <canvas id="stage"></canvas>
  </div>
  <div class="readout">
    <span>步数: <span class="mono" id="readStep">5</span></span>
    <span>坐标: <span class="mono" id="readCoord">(0.328, 2.488)</span></span>
    <span>f值: <span class="mono" id="readF">-6.082</span></span>
  </div>
</div>
<script>
const DEG = Math.PI / 180;
const root = document.documentElement;
function css(v) { return getComputedStyle(root).getPropertyValue(v).trim(); }

// math model
function project(x, y, z, az, el) {
  const ca = Math.cos(az * DEG), sa = Math.sin(az * DEG);
  const ce = Math.cos(el * DEG), se = Math.sin(el * DEG);
  const x1 = x * ca + z * sa;
  const y1 = y;
  const z1 = -x * sa + z * ca;
  const x2 = x1;
  const y2 = y1 * ce - z1 * se;
  return { sx: x2, sy: -y2 };
}

function gdPoint(t) {
  const x = Math.pow(0.8, t);
  const y = Math.pow(1.2, t);
  return { x, y, f: x*x - y*y };
}

// verification
(function() {
  const p5 = gdPoint(5);
  console.assert(Math.abs(p5.x - 0.328) < 0.001, 'x');
  console.assert(Math.abs(p5.y - 2.488) < 0.001, 'y');
  console.assert(Math.abs(p5.f + 6.082) < 0.1, 'f');
  const t = project(1,1,0,45,30);
  console.assert(!isNaN(t.sx) && !isNaN(t.sy), 'project');
})();

// state
let azimuth = 45, elevation = 30, step = 5;
const canvas = document.getElementById('stage');
const ctx = canvas.getContext('2d');
let W, H;

function setupCanvas() {
  const wrap = document.getElementById('stageWrap');
  const rect = wrap.getBoundingClientRect();
  const w = rect.width, h = rect.height;
  const aspect = 16/9;
  let cw, ch;
  if (w / h > aspect) { ch = h; cw = h * aspect; }
  else { cw = w; ch = w / aspect; }
  W = canvas.width = Math.round(cw);
  H = canvas.height = Math.round(ch);
  canvas.style.width = W + 'px';
  canvas.style.height = H + 'px';
}

function isDarkBg() {
  const bg = css('--bg');
  const m = bg.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
  if (m) {
    const r = +m[1], g = +m[2], b = +m[3];
    return 0.299*r + 0.587*g + 0.114*b < 128;
  }
  return true;
}

function update() {
  const accent = css('--accent');
  const line = css('--line');
  const ink = css('--ink');
  const text2 = css('--text2');
  const dark = isDarkBg();

  // compute complementary color for y-direction curve
  const acR = parseInt(accent.slice(1,3),16) || 0;
  const acG = parseInt(accent.slice(3,5),16) || 0;
  const acB = parseInt(accent.slice(5,7),16) || 0;
  const comp = '#' + (255-acR).toString(16).padStart(2,'0')
             + (255-acG).toString(16).padStart(2,'0')
             + (255-acB).toString(16).padStart(2,'0');

  // collect all points for bounding box
  const pts = [];
  const gridX = [], gridY = [];
  for (let x = -3; x <= 3; x += 0.3) gridX.push(x);
  gridY = gridX.slice();

  // grid vertices
  const gridPts = [];
  for (let x of gridX) {
    for (let y of gridY) {
      const z = x*x - y*y;
      const p = project(x, y, z, azimuth, elevation);
      gridPts.push({x,y,z,sx:p.sx,sy:p.sy});
      pts.push(p);
    }
  }

  // x-direction highlight (y=0)
  const xCurve = [];
  for (let x = -3; x <= 3; x += 0.05) {
    const z = x*x;
    const p = project(x, 0, z, azimuth, elevation);
    xCurve.push(p);
    pts.push(p);
  }

  // y-direction highlight (x=0)
  const yCurve = [];
  for (let y = -3; y <= 3; y += 0.05) {
    const z = -y*y;
    const p = project(0, y, z, azimuth, elevation);
    yCurve.push(p);
    pts.push(p);
  }

  // gradient descent trajectory
  const traj = [];
  for (let t = 0; t <= step; t++) {
    const g = gdPoint(t);
    const p = project(g.x, g.y, g.f, azimuth, elevation);
    traj.push(p);
    pts.push(p);
  }

  // bounding box
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (let p of pts) {
    if (p.sx < minX) minX = p.sx;
    if (p.sx > maxX) maxX = p.sx;
    if (p.sy < minY) minY = p.sy;
    if (p.sy > maxY) maxY = p.sy;
  }
  const rangeX = maxX - minX || 1;
  const rangeY = maxY - minY || 1;
  const scale = Math.min(W / rangeX, H / rangeY) * 0.85;
  const offX = (W - (minX + maxX) * scale) / 2;
  const offY = (H - (minY + maxY) * scale) / 2;

  function toScreen(p) {
    return { x: p.sx * scale + offX, y: p.sy * scale + offY };
  }

  ctx.clearRect(0, 0, W, H);

  // draw grid
  ctx.strokeStyle = line;
  ctx.lineWidth = 0.5;
  // x-lines
  for (let i = 0; i < gridX.length; i++) {
    ctx.beginPath();
    for (let j = 0; j < gridY.length; j++) {
      const idx = i * gridY.length + j;
      const s = toScreen(gridPts[idx]);
      if (j === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    }
    ctx.stroke();
  }
  // y-lines
  for (let j = 0; j < gridY.length; j++) {
    ctx.beginPath();
    for (let i = 0; i < gridX.length; i++) {
      const idx = i * gridY.length + j;
      const s = toScreen(gridPts[idx]);
      if (i === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    }
    ctx.stroke();
  }

  // x-direction highlight (accent)
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2.5;
  ctx.setLineDash([]);
  ctx.beginPath();
  for (let i = 0; i < xCurve.length; i++) {
    const s = toScreen(xCurve[i]);
    if (i === 0) ctx.moveTo(s.x, s.y);
    else ctx.lineTo(s.x, s.y);
  }
  ctx.stroke();

  // y-direction highlight (complement)
  ctx.strokeStyle = comp;
  ctx.lineWidth = 2.5;
  ctx.setLineDash([6, 4]);
  ctx.beginPath();
  for (let i = 0; i < yCurve.length; i++) {
    const s = toScreen(yCurve[i]);
    if (i === 0) ctx.moveTo(s.x, s.y);
    else ctx.lineTo(s.x, s.y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  // trajectory line (fade)
  for (let t = 0; t < traj.length - 1; t++) {
    const alpha = 0.15 + 0.85 * (t / (traj.length - 1));
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1.5;
    const s0 = toScreen(traj[t]);
    const s1 = toScreen(traj[t+1]);
    ctx.beginPath();
    ctx.moveTo(s0.x, s0.y);
    ctx.lineTo(s1.x, s1.y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // current point (glow ball)
  const last = toScreen(traj[traj.length-1]);
  if (dark) {
    ctx.shadowColor = accent;
    ctx.shadowBlur = 16;
  }
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(last.x, last.y, 6, 0, 2*Math.PI);
  ctx.fill();
  ctx.shadowBlur = 0;
  if (!dark) {
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(last.x, last.y, 9, 0, 2*Math.PI);
    ctx.stroke();
  }

  // legend
  const lx = 12, ly = 18;
  ctx.font = '12px ' + css('--sans');
  ctx.textBaseline = 'top';
  // x legend
  ctx.fillStyle = accent;
  ctx.fillRect(lx, ly, 14, 4);
  ctx.fillStyle = ink;
  ctx.fillText('沿x方向', lx + 20, ly - 4);
  // y legend
  ctx.fillStyle = comp;
  ctx.fillRect(lx, ly + 20, 14, 4);
  ctx.fillStyle = ink;
  ctx.fillText('沿y方向', lx + 20, ly + 16);

  // update readout
  const g = gdPoint(step);
  document.getElementById('readStep').textContent = step;
  document.getElementById('readCoord').textContent = '(' + g.x.toFixed(3) + ', ' + g.y.toFixed(3) + ')';
  document.getElementById('readF').textContent = g.f.toFixed(3);
  document.getElementById('stepVal').textContent = step;
}

// interactions
let dragging = false, startX, startY, startAz, startEl;
canvas.addEventListener('mousedown', (e) => {
  dragging = true;
  startX = e.clientX; startY = e.clientY;
  startAz = azimuth; startEl = elevation;
  canvas.style.cursor = 'grabbing';
});
window.addEventListener('mousemove', (e) => {
  if (!dragging) return;
  const dx = e.clientX - startX;
  const dy = e.clientY - startY;
  azimuth = startAz + dx * 0.5;
  elevation = Math.min(90, Math.max(0, startEl + dy * 0.5));
  update();
});
window.addEventListener('mouseup', () => {
  if (dragging) {
    dragging = false;
    canvas.style.cursor = 'grab';
  }
});
canvas.style.cursor = 'grab';

document.getElementById('step').addEventListener('input', (e) => {
  step = parseInt(e.target.value);
  update();
});

// init
setupCanvas();
update();

// handle theme change
new MutationObserver(update).observe(root, {attributes:true, attributeFilter:['data-theme']});
</script>
</widget_code>
